from lib import *
S = SS('w5')
steps = [
    step("先看这台机器:ifconfig 里没有任何 vlan 接口,networksetup -listVLANs 报 There are no VLANs currently configured on this system。在真实网口 en0 上用 `vlan` 过滤器抓 20 秒,抓到 0 个带 802.1Q 标签的帧——接入口(access port)上交换机已经把标签剥掉,主机看到的是普通帧;标签只出现在交换机之间的干道(trunk)上。", t=tl(S(1)), mark=lidx(S(1), 'en0 上 `vlan`'), done=lidx(S(1), 'ifconfig 里含 vlan', 'networksetup'), kv=KV([['主机的网口', '普通帧,不带标签'], ['交换机之间的 trunk', '带 802.1Q 标签'], ['这台机器', '没有 VLAN 接口,20 秒抓到 0 个带标签帧']], ['主机的网口'])),
    step("这台机器造不出 VLAN 流量(建 VLAN 接口、注入带标签的帧都要 root 或写 bpf),所以按 IEEE 802.1Q 的格式用 struct 自己拼一个带标签的帧,写成 pcap,让 tcpdump 来解析。没标签的帧:目的 MAC、源 MAC 之后是 EtherType 0800;带标签的帧在这两者之间多出 4 字节 81 00 a0 64:TPID=8100 表示后面是 802.1Q 标签,TCI=0xa064 拆开是 PCP=5(3 位优先级)、DEI=0(1 位)、VID=100(12 位 VLAN 号),原来的 EtherType 0800 被挤到标签后面。tcpdump 解析出 vlan 100, p 5, ethertype IPv4——与拼进去的一致。(这一节验证的是格式,不是真实 VLAN 流量。)", t=tl(S(2)), mark=lidx(S(2), '带标签的帧', 'TCI 拆开', 'tcpdump 解析'), done=lidx(S(2), '没标签的帧', '目的 MAC、源 MAC 之后多出'), b=bars([['TPID', 16, '16 位 0x8100'], ['PCP', 3, '3 位 = 5'], ['DEI', 1, '1 位 = 0'], ['VID', 12, '12 位 = 100']], 16, mark=[3], done=[0, 1, 2]), kv=KV([['TPID', '0x8100:后面是 802.1Q 标签'], ['TCI', 'PCP 3 位 + DEI 1 位 + VID 12 位'], ['标签位置', '源 MAC 之后、EtherType 之前']], ['TCI'])),
    step("标签让帧长 +4:载荷 1500 字节(标准 MTU)的帧,没标签是 1514 字节(不含 FCS),带标签是 1518,含 FCS 分别是 1518 与 1522——交换机和网卡要能收发 1522 字节的最大帧,而 VLAN 子接口的 MTU 仍是 1500。最小帧按规范(不是实测):整个帧含 FCS 至少 64 字节,所以没标签时载荷至少 46 字节,带标签时载荷至少 42 字节,更短的由网卡补零。", t=tl(S(3)), mark=lidx(S(3), '载荷 1500', '最小帧'), done=lidx(S(3), '载荷 1500'), b=bars([['没标签 1500 载荷', 1514, '1514 B'], ['带标签 1500 载荷', 1518, '1518 B'], ['带标签含 FCS', 1522, '1522 B']], 1522, mark=[1, 2], done=[0]), kv=KV([['带一层标签', '帧长 +4'], ['最大帧(含 FCS)', '1518 → 1522'], ['MTU', '仍是 1500']], ['带一层标签'])),
    step("Q-in-Q(802.1ad):运营商在客户的标签外面再套一层 S-TAG,外层 TPID=0x88a8,内层仍是 0x8100。拼出的双层标签帧前 26 字节是 … 88 a8 00 c8 81 00 a0 64 08 00 …,tcpdump 解析成 ethertype 802.1Q-QinQ (0x88a8), vlan 200, p 0, ethertype 802.1Q (0x8100), vlan 100, p 5, ethertype IPv4;帧长 60 字节,比没标签的多 8 字节(2 个标签 × 4)。", t=tl(S(4)), mark=lidx(S(4), 'tcpdump 解析', '帧长 60'), done=lidx(S(4), '双层标签的帧'), kv=KV([['外层 S-TAG', 'TPID 0x88a8,VLAN 200'], ['内层 C-TAG', 'TPID 0x8100,VLAN 100'], ['帧长', '比没标签 +8']], ['外层 S-TAG'])),
    step("VLAN 号只有 12 位,取值 0~4095;0(只带优先级、不属于任何 VLAN)和 4095(保留)不能用来划分,实际可用 1~4094 共 4094 个;PCP 3 位,0~7 共 8 级。用代码把 8 × 4096 = 32768 种 (PCP, VID) 组合打包再解出来全部一致(True)。VLAN 1 通常是默认 VLAN;很多交换机的 trunk 上默认 VLAN 的帧不带标签(native VLAN),这是配置错误的常见来源——本机没法实验,所以只记在这里。", t=tl(S(5)), mark=lidx(S(5), '全部一致', '可用 VLAN 号'), done=lidx(S(5), '8 × 4096'), b=bars([['VID 取值范围', 4096, '0~4095'], ['可用 VLAN', 4094, '1~4094'], ['PCP 级别', 8, '0~7']], 4096, mark=[1], done=[0, 2]), kv=KV([['VID', '12 位:4094 个可用'], ['PCP', '3 位:8 级优先级'], ['native VLAN', '不带标签的那个 VLAN(未实测)']], ['VID'])),
]
A = mkartw('w5', 5, '网络协议,VLAN,802.1Q,QinQ,以太网标签,tcpdump,真实验证,动画演示',
    '按 IEEE 802.1Q 用 struct 拼出带标签的以太网帧并让 tcpdump 解析(TPID 0x8100,TCI 拆成 PCP / DEI / VID,帧长 +4;Q-in-Q 的 0x88a8 外层标签 +8);这台机器的真实网口 20 秒内没有抓到任何带标签的帧;VLAN 号 12 位、可用 4094 个、PCP 8 级,32768 种组合打包后全部一致。',
    'VLAN 的标签只有 4 个字节,却让一张物理网络变成很多个逻辑网络。这篇把 802.1Q 标签按位拆开,拼一个真正的带标签帧让 tcpdump 解析,并说清楚它对帧长、MTU 的影响,以及这台机器上为什么看不到真实的标签。',
    [('+4 字节', '一层 802.1Q 标签让帧长增加的字节数(Q-in-Q 两层 +8)'), ('4094', '12 位 VLAN 号里实际可用的数量(0 和 4095 保留)'), ('0 个', '真实网口 en0 上 20 秒内抓到的带标签帧——接入口上标签已被剥掉')],
    [('标签的位置和格式', '<p>在源 MAC 之后、EtherType 之前插入 4 字节:TPID=0x8100(表示这是 802.1Q 标签),接着 16 位的 TCI,拆成 PCP(3 位优先级)、DEI(1 位)和 VID(12 位)。</p>'),
     ('主机看不到标签', '<p>接入口上交换机已经把标签剥掉,只有交换机之间的 trunk 才带标签,所以在普通主机上抓包看不到(实测 20 秒 0 个)。</p>'),
     ('对帧长的影响', '<p>带标签的帧最大 1518(不含 FCS),不带的是 1514;VLAN 接口的 MTU 仍是 1500。</p>'),
     ('Q-in-Q', '<p>运营商在客户标签外再加一层 0x88a8 的 S-TAG,帧长再 +4。</p>'),
     ('取值范围', '<p>VID 12 位,可用 1~4094;PCP 3 位 8 级。native VLAN(trunk 上不带标签的那个)是常见的配置陷阱。</p>')],
    steps,
    [ENV_W + '。第一节是真实环境的观察;第二到五节用 struct 自己拼帧、写成 pcap 再用 tcpdump -r 与 dpkt 解析——验证的是 802.1Q 的帧格式,而不是真实 VLAN 流量(这台机器无法创建 VLAN 接口、也不能注入原始帧)',
     '没有验证:真实交换机的 trunk / access 行为;native VLAN 错配;VLAN 间路由;STP / 多实例生成树;QoS 对 PCP 的映射;VXLAN 等覆盖网络(见“VPN 隧道封装”一篇);802.1ad 的 DEI/DE 位在运营商网络里的用法'],
    'VLAN 与 802.1Q')
